// context-meter: one row of pills above the prompt (the account's session and
// weekly limits, the context window, the prompt cache, this session's cost),
// and ;name prompt snippets. /meter hides or shows the row.
//
// The engine takes each event once per plugin and follows `$` only into
// functions in this file, so this file holds every hook and every engine call,
// grouped by feature. The other files are pure: band.tsx, account.ts and
// pill.tsx draw, format.ts formats, usage.ts, cache.ts, limits.ts and
// snippets.ts turn engine figures and files into values.
//
// Band: the pills, and a Compact button once the context passes `compactAt`.
// Limits: a session only hears them on its own replies, so each session leaves
// its newest reading in one file and every session shows the newest of them,
// checking every 30 seconds. A reading counts only when it arrives with a
// reply, stamped with the reply's time: what an idle session still holds from
// its last reply is never shared, so a reload of many sessions at once can't
// overwrite a fresh reading.
// Snippets: ~/.claude/snippets/<name>.md and the project's .claude/snippets
// (the project's win), expanded wherever ;name appears in a prompt.
// Paths under ~/.claude follow CLAUDE_CONFIG_DIR when it is set.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionContextUsage, SessionRateLimit } from 'claude-code'

import type { Reading } from '../types'
import { band, bandPills } from './band'
import type { TtlConfig } from './cache'
import { cacheState, cacheTtl, settingTtl } from './cache'
import type { SharedLimits } from './limits'
import { SHARED_FILE, limitsOf, parseShared } from './limits'
import type { Snippet } from './snippets'
import { USAGE, expand, listing, mayExpand, parseAdd, parseSnippet, snippetName } from './snippets'
import { readingOf } from './usage'

const COMPACT_AT = 70
// How often the countdowns redraw and a session looks for a newer limits reading.
const TICK_EVERY = 30_000

const context = atom({ plugin: 'context-meter', key: 'context' } as const, null)
const limits = atom({ plugin: 'context-meter', key: 'limits' } as const, null)
const accountLimits = atom({ plugin: 'context-meter', key: 'accountLimits' } as const, [])
const accountLimitsAt = atom({ plugin: 'context-meter', key: 'accountLimitsAt' } as const, null)
const cost = atom({ plugin: 'context-meter', key: 'cost' } as const, null)
const isHidden = atom({ plugin: 'context-meter', key: 'isHidden' } as const, false)
const isCompacting = atom({ plugin: 'context-meter', key: 'isCompacting' } as const, false)
const lastRequestAt = atom({ plugin: 'context-meter', key: 'lastRequestAt' } as const, null)

export const register: Register = (on, options) => {
  const compactAt = typeof options.compactAt === 'number' ? options.compactAt : COMPACT_AT
  // What decides the prompt cache's lifetime; read at session start.
  let ttlConfig: TtlConfig = {}
  // When the latest model reply of this load arrived; the limits a measurement
  // carries are that reply's. Null until one arrives.
  let lastReplyAt: number | null = null

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'meter', description: 'Show or hide the usage pills above the prompt' })
    await $.command.register({
      name: 'snippets',
      description: 'List prompt snippets (;name), or save one: /snippets add <name> <text>',
    })
    ttlConfig = await readTtlConfig($)
    const reading = await readingNow($)
    await update($, context, () => reading)
    // Another session's reading shows the limits before this one's first reply.
    // This session's own figures wait for its next reply: the ones it holds now
    // may be hours old.
    await syncLimits($)
    const spent = (await $.session.usage()).cost?.usd ?? null
    await update($, cost, () => spent)
    $.clock.every(TICK_EVERY, () => void tick($))

    return next(e)
  })

  // Each main-thread request reads the cached conversation and restarts its
  // timer. Every reply, a subagent's too, brings the limits.
  on('turn.step', async function* ($, e, next) {
    if (e.agentId === undefined) {
      const at = await $.clock.now()
      await update($, lastRequestAt, () => at)
    }
    const reply = yield* next(e)
    lastReplyAt = await $.clock.now()

    return reply
  })

  on('session.measure', async ($, e, next) => {
    const reading = await readingNow($, e.context)
    await update($, context, () => reading)
    // This session's own limits say which cache lifetime applies: none at all
    // after the first reply means an API key.
    if (e.changed.includes('rateLimits') || (await read($, limits)) === null) {
      await update($, limits, () => limitsOf(e.rateLimits))
    }
    if (lastReplyAt !== null) {
      await record($, e.rateLimits, lastReplyAt)
    }
    if (e.cost !== undefined) {
      const spent = e.cost.usd
      await update($, cost, () => spent)
    }

    return next(e)
  })

  // Any compaction of the main conversation, typed or the Compact button's:
  // the engine puts the compacted window in place once this dispatch ends.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && e.trigger !== 'precompute' && result.skip === undefined) {
      $.clock.after(0, () => void afterCompaction($))
    }

    return result
  })

  on('prompt.submit', async ($, e, next) => {
    if (!mayExpand(e.text, e.origin.kind)) {
      return next(e)
    }
    const expanded = expand(e.text, await loadSnippets($))
    if (expanded.used.length === 0) {
      return next(e)
    }
    $.ui.toast(`Expanded ${expanded.used.map(name => `;${name}`).join(', ')}`)

    return next({ ...e, text: expanded.text })
  })

  on('command.run', { command: 'meter' }, async $ => {
    const wasHidden = await read($, isHidden)
    await update($, isHidden, () => !wasHidden)

    return { text: wasHidden ? 'Usage pills shown.' : 'Usage pills hidden. /meter brings them back.' }
  })

  on('command.run', { command: 'snippets' }, async ($, e) => {
    const args = e.args.trim()
    if (args === '' || args === 'list') {
      return { text: listing([...(await loadSnippets($)).values()]) }
    }
    const added = parseAdd(args)

    return { text: added === null ? USAGE : await saveSnippet($, added.name, added.body) }
  })

  // The engine's own band drawing (`beneath`) stays in the row, after the pills.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) {
      return next(e)
    }
    const beneath = await next(e)
    if (await read($, isHidden)) {
      return beneath
    }
    const reading = await read($, context)
    const now = await $.clock.now()
    const ttl = cacheTtl(ttlConfig, await read($, limits), now)
    const view = {
      surface: e.surface,
      context: reading,
      cache: ttl === null ? null : cacheState(await read($, lastRequestAt), ttl, now, reading?.tokens ?? 0),
      account: { limits: await read($, accountLimits), cost: await read($, cost), now },
      onHide: () => update($, isHidden, () => true),
      compact: (await read($, isCompacting))
        ? ('busy' as const)
        : !e.props.isWorking && reading !== null && reading.percent >= compactAt
          ? () => compactNow($)
          : null,
    }
    if (bandPills(view).length === 0) {
      return beneath
    }

    return band($.ui.resolve(e), view, beneath)
  })
}

// Band

// Claude Code's configuration folder: CLAUDE_CONFIG_DIR, else ~/.claude.
async function configFolder($: EngineInterface): Promise<string | null> {
  const configured = await $.env.get('CLAUDE_CONFIG_DIR')
  if (configured !== undefined && configured !== '') {
    return configured
  }
  const home = await $.env.get('HOME')

  return home === undefined ? null : `${home}/.claude`
}

// The prompt cache's lifetime settings: the environment, then the most
// specific settings file that sets promptCacheTtl (local, project, yours).
async function readTtlConfig($: EngineInterface): Promise<TtlConfig> {
  const config = await configFolder($)
  const files = ['.claude/settings.local.json', '.claude/settings.json', ...(config === null ? [] : [`${config}/settings.json`])]
  let setting: unknown
  for (const file of files) {
    try {
      setting = (await $.fs.exists(file)) ? settingTtl(await $.fs.read(file)) : undefined
    } catch {
      setting = undefined
    }
    if (setting !== undefined) {
      break
    }
  }

  return {
    env: await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL'),
    force5m: await $.env.get('FORCE_PROMPT_CACHING_5M'),
    enable1h: await $.env.get('ENABLE_PROMPT_CACHING_1H'),
    setting,
  }
}

// The window's fill: the last response's figures, or, until the live window
// has a response (a fresh session, or one just compacted), the engine's own
// estimate, which it makes locally without a request.
async function readingNow($: EngineInterface, live?: SessionContextUsage): Promise<Reading | null> {
  const usage = live ?? (await $.session.usage()).context
  if (usage.tokens !== undefined) {
    return readingOf(usage)
  }
  try {
    return readingOf(usage, (await $.session.usage({ breakdown: 'summary' })).context.breakdown?.totalTokens)
  } catch {
    return readingOf(usage)
  }
}

async function afterCompaction($: EngineInterface) {
  // The compacted conversation is a new prefix: its cache starts with the next request.
  await update($, lastRequestAt, () => null)
  const reading = await readingNow($)
  await update($, context, () => reading)
}

async function tick($: EngineInterface) {
  await syncLimits($)
  $.ui.invalidate('ui.render')
}

// The Compact button runs Claude Code's own /compact. A plugin can't compact
// under the press that asked (the engine holds that dispatch), and in an SDK
// session, which the desktop's Code tab is, only the /compact command compacts.
// So the press only marks the band busy and starts /compact just after; the
// session.compact hook reads the compacted window.
async function compactNow($: EngineInterface) {
  if (await read($, isCompacting)) {
    return
  }
  await update($, isCompacting, () => true)
  $.clock.after(0, () => void runCompact($))
}

async function runCompact($: EngineInterface) {
  try {
    await $.command.run({ command: 'compact' })
  } catch (error) {
    const reason = error instanceof Error ? error.message.replace(/^[\w-]+: /, '') : String(error)
    $.ui.toast(`Compaction failed: ${reason}`)
  } finally {
    await update($, isCompacting, () => false)
  }
}

// Limits

async function record($: EngineInterface, windows: readonly SessionRateLimit[], observedAt: number) {
  if (windows.length > 0) {
    await adoptLimits($, { observedAt, limits: limitsOf(windows) }, true)
  }
}

// Takes a reading when it is newer than the one shown; this session's own
// readings are also left for the other sessions.
async function adoptLimits($: EngineInterface, reading: SharedLimits, isOwn: boolean) {
  const shownAt = await read($, accountLimitsAt)
  if (shownAt !== null && shownAt >= reading.observedAt) {
    return
  }
  await update($, accountLimits, () => reading.limits)
  await update($, accountLimitsAt, () => reading.observedAt)
  if (!isOwn) {
    return
  }
  const path = await sharedPath($)
  const shared = path === null ? null : await readShared($, path)
  if (path !== null && (shared === null || shared.observedAt < reading.observedAt)) {
    try {
      await $.fs.write(path, JSON.stringify(reading))
    } catch {
      // Sharing is best effort; this session still shows its own reading.
    }
  }
}

async function syncLimits($: EngineInterface) {
  const path = await sharedPath($)
  const shared = path === null ? null : await readShared($, path)
  if (shared !== null) {
    await adoptLimits($, shared, false)
  }
}

async function sharedPath($: EngineInterface): Promise<string | null> {
  const config = await configFolder($)

  return config === null ? null : `${config}/${SHARED_FILE}`
}

async function readShared($: EngineInterface, path: string): Promise<SharedLimits | null> {
  try {
    return (await $.fs.exists(path)) ? parseShared(await $.fs.read(path)) : null
  } catch {
    return null
  }
}

// Snippets

async function snippetFolders($: EngineInterface): Promise<string[]> {
  const config = await configFolder($)

  // Later folders win: the project's snippets override yours.
  return [...(config === null ? [] : [`${config}/snippets`]), '.claude/snippets']
}

async function loadSnippets($: EngineInterface): Promise<Map<string, Snippet>> {
  const found = new Map<string, Snippet>()
  for (const folder of await snippetFolders($)) {
    if (!(await $.fs.exists(folder))) {
      continue
    }
    for (const entry of await $.fs.list(folder)) {
      const name = entry.kind === 'file' ? snippetName(entry.name) : null
      if (name === null) {
        continue
      }
      const path = `${folder}/${entry.name}`
      try {
        found.set(name, { name, path, ...parseSnippet(await $.fs.read(path)) })
      } catch {
        // An unreadable file is left out; the rest still expand.
      }
    }
  }

  return found
}

async function saveSnippet($: EngineInterface, name: string, body: string): Promise<string> {
  const config = await configFolder($)
  if (config === null) {
    return 'Could not find your Claude Code folder to save the snippet in.'
  }
  const path = `${config}/snippets/${name}.md`
  const existed = await $.fs.exists(path)
  await $.fs.write(path, `${body}\n`)

  return `${existed ? 'Updated' : 'Saved'} ;${name} in ${path}`
}

