// The band above the prompt: a plain function of what the hooks recorded.
// One row of pills (the account's limits, the context, the prompt cache, the
// session's cost), then Compact and Hide on the right:
//
//   (◷ 5h ━┃━ 20% │ 2h 40m) (▦ 7d ━━┃ 58% │ 1d 7h) (◔ Context ━━ 8%) (⧗ Cache 42m │ 1h) ($54.21)              Hide
//
// Until a fresh or just-compacted window has a response, the context figure is
// the engine's estimate: `~8%`.

import type { ElementTable, RenderElement, RenderSurface } from 'claude-code'

import type { Reading } from '../types'
import type { AccountView } from './account'
import { costPills, limitPills } from './account'
import type { CacheState } from './cache'
import { TTL_MS } from './cache'
import { percentText, short, toneFor, until } from './format'
import type { Pill } from './pill'
import { pills } from './pill'

type BandView = {
  surface: RenderSurface
  context: Reading | null
  cache: CacheState | null
  account: AccountView
  onHide: () => void
  // A press handler while the Compact button shows, 'busy' while compacting.
  compact: (() => void) | 'busy' | null
}

export function band(t: ElementTable, view: BandView, beneath: RenderElement) {
  const { Box, Text, Button } = t
  const own = bandPills(view)

  // One line, never wrapped: the pills on the left (clipped, not wrapped, when
  // the window is too narrow), what draws beneath, the buttons on the right.
  // What draws beneath stays outside the clipped Box: the engine refuses its
  // own drawing under a Box with `overflow`, and then draws nothing of ours.
  return (
    <Box flexDirection="row" flexWrap="nowrap" alignItems="center" columnGap={1} flexGrow={1}>
      <Box flexDirection="row" flexWrap="nowrap" alignItems="center" columnGap={1} flexShrink={1} overflow="hidden">
        {pills(t, view.surface, own)}
      </Box>
      {beneath}
      <Box flexGrow={1} />
      <Box flexDirection="row" flexWrap="nowrap" alignItems="center" columnGap={2} flexShrink={0}>
        {view.compact === 'busy' && <Text dimColor>Compacting…</Text>}
        {typeof view.compact === 'function' && (
          <Button key="compact" label="Compact" variant="primary" onPress={view.compact} />
        )}
        <Button key="hide" label="Hide" plain dimColor onPress={view.onHide} />
      </Box>
    </Box>
  )
}

// Every pill the band has figures for; empty before any.
export const bandPills = (view: Pick<BandView, 'context' | 'cache' | 'account'>): Pill[] => [
  ...limitPills(view.account),
  ...(view.context === null ? [] : [contextPill(view.context)]),
  ...(view.cache === null ? [] : [cachePill(view.cache)]),
  ...costPills(view.account),
]

function contextPill(reading: Reading): Pill {
  const tone = toneFor(reading.percent)
  const about = reading.isEstimate === true ? '~' : ''

  return {
    key: 'context',
    hue: 'sky',
    icon: 'pie',
    label: 'Context',
    meter: { fill: reading.percent },
    value: `${about}${percentText(reading.percent)}`,
    ...(tone === 'success' ? {} : { loud: tone }),
    alt:
      `Context ${about}${percentText(reading.percent)} full: ${about}${short(reading.tokens)} of ${short(reading.window)} tokens` +
      (reading.isEstimate === true ? ", the engine's estimate until the next reply" : ''),
  }
}

// The prompt cache: the time left on its lifetime, louder as it runs out; once
// cold, the next request writes the whole context again.
function cachePill(cache: CacheState): Pill {
  const base = { key: 'cache', hue: 'pink', icon: 'hourglass', label: 'Cache' } as const
  if (cache.remaining <= 0) {
    return {
      ...base,
      value: 'cold',
      loud: 'warning',
      after: { text: `re-cache ${short(cache.tokens)}` },
      alt: `Prompt cache cold: the next request writes ${short(cache.tokens)} tokens to it again`,
    }
  }
  const left = cache.remaining / TTL_MS[cache.ttl]

  return {
    ...base,
    value: until(cache.remaining),
    ...(left > 0.25 ? {} : { loud: left > 0.1 ? 'warning' : 'error' }),
    after: { text: cache.ttl },
    alt: `Prompt cache: ${until(cache.remaining)} left of its ${cache.ttl} lifetime`,
  }
}

