// Pure prompt-cache logic: which lifetime the session's cache has, and how
// much of it is left.
//
// Every main-thread request reads the cached conversation and restarts its
// timer, measured from the request's start. Once the timer runs out the next
// request writes the whole context to the cache again, at the write price.

import type { Limit } from '../types'

export type CacheTtl = '5m' | '1h'

export const TTL_MS: Record<CacheTtl, number> = { '5m': 5 * 60_000, '1h': 60 * 60_000 }

// What decides the lifetime, read once at session start.
export type TtlConfig = {
  // CLAUDE_CODE_PROMPT_CACHE_TTL, FORCE_PROMPT_CACHING_5M, ENABLE_PROMPT_CACHING_1H
  env?: string
  force5m?: string
  enable1h?: string
  // The promptCacheTtl setting, from the most specific settings file that sets it.
  setting?: unknown
}

const isTtl = (value: unknown): value is CacheTtl => value === '5m' || value === '1h'

const isOn = (value: string | undefined) =>
  value !== undefined && value !== '' && value !== '0' && value.toLowerCase() !== 'false'

// The lifetime as Claude Code chooses it: the environment variable, then the
// setting, then automatic: 1 hour on a Claude subscription within its usage
// limits, 5 minutes past them or on an API key. `limits` is null until the
// session's first reply says which; the lifetime is unknown until then.
export function cacheTtl(config: TtlConfig, limits: readonly Limit[] | null, now: number): CacheTtl | null {
  if (isTtl(config.env)) return config.env
  if (isOn(config.force5m)) return '5m'
  if (isTtl(config.setting)) return config.setting
  if (isOn(config.enable1h)) return '1h'
  if (limits === null) return null
  const live = limits.filter(limit => limit.resetsAt === undefined || limit.resetsAt > now)
  if (live.length === 0) return '5m'

  return live.some(limit => limit.percent >= 100) ? '5m' : '1h'
}

// The promptCacheTtl a settings file sets, or undefined.
export function settingTtl(text: string): unknown {
  try {
    const data: unknown = JSON.parse(text)
    return typeof data === 'object' && data !== null ? (data as { promptCacheTtl?: unknown }).promptCacheTtl : undefined
  } catch {
    return undefined
  }
}

// The cache's state for the band, or null before the first request.
export type CacheState = { ttl: CacheTtl; remaining: number; tokens: number }

export function cacheState(lastRequestAt: number | null, ttl: CacheTtl, now: number, tokens: number): CacheState | null {
  if (lastRequestAt === null) {
    return null
  }

  return { ttl, remaining: lastRequestAt + TTL_MS[ttl] - now, tokens }
}

