// Pure limits logic: the engine's rate-limit windows into readings, and the
// file the sessions share them through.

import type { SessionRateLimit } from 'claude-code'

import type { Limit } from '../types'

export function limitsOf(windows: readonly SessionRateLimit[]): Limit[] {
  return windows.map(one => {
    const resetsAt = one.resetsAt === undefined ? NaN : Date.parse(one.resetsAt)

    return Number.isNaN(resetsAt)
      ? { kind: one.kind, percent: one.percentUsed }
      : { kind: one.kind, percent: one.percentUsed, resetsAt }
  })
}

// The limits are the account's, shared by every session, but each session
// only hears them on its own replies. So each session leaves its newest
// reading in one file, and every session shows the newest of them.
export type SharedLimits = { observedAt: number; limits: Limit[] }

// Under Claude Code's configuration folder, whatever the marketplace is named.
export const SHARED_FILE = 'plugins/data/context-meter/limits.json'

// The file's reading, or null for a missing, partial or foreign file.
export function parseShared(text: string): SharedLimits | null {
  try {
    const data: unknown = JSON.parse(text)
    if (typeof data !== 'object' || data === null) {
      return null
    }
    const { observedAt, limits } = data as { observedAt?: unknown; limits?: unknown }
    if (typeof observedAt !== 'number' || !Array.isArray(limits) || !limits.every(isLimit)) {
      return null
    }

    return { observedAt, limits }
  } catch {
    return null
  }
}

const isLimit = (value: unknown): value is Limit => {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const { kind, percent, resetsAt } = value as { kind?: unknown; percent?: unknown; resetsAt?: unknown }

  return typeof kind === 'string' && typeof percent === 'number' && (resetsAt === undefined || typeof resetsAt === 'number')
}

