// Pure snippet logic: parsing snippet files, expanding ;name tokens in a
// prompt, and the /snippets listing. register.tsx reads and writes the files.
//
// A snippet is a Markdown file, `review.md` for ;review, with an optional
// front matter `description:` line that labels it in /snippets.

export type Snippet = { name: string; body: string; description: string; path: string }

const NAME = /^[a-z0-9][a-z0-9_-]*$/

// `;name` at the start or after whitespace, ending at whitespace, punctuation or the end.
const TOKEN = /(^|\s);([a-z0-9][a-z0-9_-]*)(?=$|[\s.,!?:)])/gi

// Whether a prompt could hold a snippet: not a slash command, not a task notification.
export const mayExpand = (text: string, origin: string): boolean =>
  origin !== 'task-notification' && !text.trimStart().startsWith('/') && text.includes(';')

// `review.md` → `review`, or null for a file that is not a snippet.
export function snippetName(fileName: string): string | null {
  if (!fileName.endsWith('.md')) {
    return null
  }
  const name = fileName.slice(0, -'.md'.length).toLowerCase()

  return NAME.test(name) ? name : null
}

export function parseSnippet(source: string): { body: string; description: string } {
  const text = source.replace(/\r\n/g, '\n')
  const front = /^---\n([\s\S]*?)\n---\n?/.exec(text)
  const body = (front === null ? text : text.slice(front[0].length)).trim()
  const described = front === null ? undefined : /^description:\s*(.+)$/m.exec(front[1] ?? '')?.[1]

  return { body, description: (described ?? body.split('\n')[0] ?? '').trim() }
}

export function expand(text: string, known: ReadonlyMap<string, Snippet>): { text: string; used: string[] } {
  const used = new Set<string>()
  const expanded = text.replace(TOKEN, (whole: string, lead: string, name: string) => {
    const snippet = known.get(name.toLowerCase())
    if (snippet === undefined || snippet.body === '') {
      return whole
    }
    used.add(snippet.name)

    return `${lead}${snippet.body}`
  })

  return { text: expanded, used: [...used] }
}

// `/snippets add <name> <text>` → the name and text, or null when either is missing.
export function parseAdd(args: string): { name: string; body: string } | null {
  const match = /^add\s+(\S+)\s+([\s\S]+)$/.exec(args.trim())
  const name = match?.[1]?.toLowerCase()
  const body = match?.[2]?.trim()

  return name !== undefined && body !== undefined && NAME.test(name) && body !== '' ? { name, body } : null
}

export const USAGE = 'Usage: /snippets lists them; /snippets add <name> <text> saves one (a name is letters, digits, - or _).'

export function listing(all: readonly Snippet[]): string {
  if (all.length === 0) {
    return [
      'No snippets yet. Save one with:',
      '  /snippets add review Review my uncommitted changes for bugs',
      "or put Markdown files in ~/.claude/snippets (or a project's .claude/snippets).",
      'Then type ;review anywhere in a prompt.',
    ].join('\n')
  }
  const width = Math.max(...all.map(snippet => snippet.name.length)) + 1
  const rows = [...all]
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(snippet => `  ;${snippet.name.padEnd(width)} ${clip(snippet.description, 70)}`)

  return ['Snippets (type ;name anywhere in a prompt):', ...rows, '', 'Save one: /snippets add <name> <text>'].join('\n')
}

const clip = (text: string, max: number) => (text.length > max ? `${text.slice(0, max - 1)}…` : text)

