// Pure usage math: the engine's figures turned into what the band keeps.

import type { SessionContextUsage } from 'claude-code'

import type { Reading } from '../types'

// The window's fill as the last response reported it. A fresh session, or one
// just compacted, has no response yet: then `estimate`, the engine's estimate
// of what the window holds, when there is one.
export function readingOf(window: SessionContextUsage, estimate?: number): Reading | null {
  if (!window.window) {
    return null
  }
  if (window.tokens !== undefined) {
    return { tokens: window.tokens, window: window.window, percent: window.percent ?? percentOf(window.tokens, window.window) }
  }

  return estimate === undefined
    ? null
    : { tokens: estimate, window: window.window, percent: percentOf(estimate, window.window), isEstimate: true }
}

const percentOf = (tokens: number, window: number) => Math.round((tokens / window) * 100)

