// The account's pills: the session (5-hour) and weekly limits, and this
// session's cost.
//
//   (◷ 5h ━┃━━ 20% │ 2h 40m) (▦ 7d ━━━┃ 58% │ 1d 7h)  …  ($54.21)
//
// Each limit's meter is the share used, and its mark how far through the
// window the clock is: a fill past the mark is spending faster than the window
// lasts. After the rule, the time until the window resets. $ is the session's
// cost, from Claude Code's ledger.

import type { Limit } from '../types'
import { dollars, limitLabel, limitOrder, percentText, toneFor, until } from './format'
import type { Hue, Icon, Pill } from './pill'

export type AccountView = { limits: readonly Limit[]; cost: number | null; now: number }

const HOUR = 3_600_000

// The windows the account has, as the pills name them.
const WINDOWS: Record<string, { label: string; hue: Hue; icon: Icon; length: number }> = {
  five_hour: { label: '5h', hue: 'teal', icon: 'gauge', length: 5 * HOUR },
  seven_day: { label: '7d', hue: 'violet', icon: 'calendar', length: 7 * 24 * HOUR },
}

const ordered = (limits: readonly Limit[]) => [...limits].sort((a, b) => limitOrder(a.kind) - limitOrder(b.kind))

// The limits' pills, session first, and the cost's.
export const limitPills = (view: AccountView): Pill[] => ordered(view.limits).map(limit => limitPill(limit, view.now))

export const costPills = (view: AccountView): Pill[] =>
  view.cost === null || view.cost <= 0
    ? []
    : [{ key: 'cost', hue: 'amber', icon: 'coin', value: dollars(view.cost), alt: `This session has cost ${dollars(view.cost)}` }]

function limitPill(limit: Limit, now: number): Pill {
  const known = WINDOWS[limit.kind]
  const name = limitLabel(limit.kind)
  const reset = limit.resetsAt !== undefined && limit.resetsAt <= now
  const percent = reset ? 0 : limit.percent
  const tone = toneFor(percent)
  const left = reset || limit.resetsAt === undefined ? null : limit.resetsAt - now
  const mark = left === null || known === undefined ? null : Math.max(0, 100 - (left / known.length) * 100)
  const said = reset ? ', reset' : left === null ? '' : `, resets in ${until(left)}`
  const passed = mark === null ? '' : `; ${Math.round(mark)}% of the window has passed`

  return {
    key: `limit-${limit.kind}`,
    hue: known?.hue ?? 'amber',
    icon: known?.icon ?? 'gauge',
    label: known?.label ?? name,
    meter: mark === null ? { fill: percent } : { fill: percent, mark },
    // Whole percents in the pill, to keep the row narrow; the words keep the exact figure.
    value: `${Math.round(percent)}%`,
    ...(tone === 'success' ? {} : { loud: tone }),
    ...(reset ? { after: { text: 'reset' } } : left === null ? {} : { after: { text: until(left) } }),
    alt: `${name} limit: ${percentText(percent)} used${said}${passed}`,
  }
}

