// Pure helpers the band draws with: no `$`, no state.

// How a figure looks: the app's theme keys.
export type Tone = 'success' | 'warning' | 'error'

// How worried a usage percentage should look.
export const toneFor = (percent: number): Tone =>
  percent >= 90 ? 'error' : percent >= 70 ? 'warning' : 'success'

// 333000 → "333k", 23500 → "23.5k", 1000000 → "1M".
export const short = (n: number): string => {
  if (n >= 1_000_000) return `${scaled(n / 1_000_000)}M`
  if (n >= 1_000) return `${scaled(n / 1_000)}k`
  return String(n)
}

const scaled = (x: number) => (x >= 100 ? String(Math.round(x)) : x.toFixed(1).replace(/\.0$/, ''))

// 4.321 → "$4.32", 0.004 → "<$0.01", 123.4 → "$123".
export const dollars = (usd: number): string =>
  usd > 0 && usd < 0.01 ? '<$0.01' : usd >= 100 ? `$${Math.round(usd)}` : `$${usd.toFixed(2)}`

const LIMIT_LABELS: Record<string, string> = {
  five_hour: 'Session',
  seven_day: 'Week',
  spend_limit: 'Spend',
}

export const limitLabel = (kind: string): string =>
  LIMIT_LABELS[kind] ?? kind.replace(/_/g, ' ').replace(/^./, first => first.toUpperCase())

// The session window first, then the week, then anything else.
export const limitOrder = (kind: string): number => {
  const at = Object.keys(LIMIT_LABELS).indexOf(kind)
  return at === -1 ? Object.keys(LIMIT_LABELS).length : at
}

export const percentText = (percent: number): string =>
  `${Number.isInteger(percent) ? percent : percent.toFixed(1)}%`

// "2h 14m", "3d 4h", "45m", "<1m": how long until a window resets.
export const until = (ms: number): string => {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return '<1m'
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  if (days > 0) return hours > 0 ? `${days}d ${hours}h` : `${days}d`
  const rest = minutes % 60
  if (hours > 0) return rest > 0 ? `${hours}h ${rest}m` : `${hours}h`
  return `${rest}m`
}

