// Pills: one figure each, the chips of the band above the prompt. The desktop
// (and every surface but the terminal) draws each pill as a small picture: a
// tinted, rounded chip with an icon, a mini meter and the figures. The terminal
// draws a run of colored text:
//
//   ◷ 5h ━━┃─── 20% │ 2h 40m    ◔ Context ━───── 8%    $4.32

import type { ElementTable, RenderElement, RenderSurface } from 'claude-code'

export type Hue = 'sky' | 'pink' | 'teal' | 'violet' | 'amber'
export type Icon = 'pie' | 'hourglass' | 'gauge' | 'calendar' | 'coin'
// A figure that should worry: the app's theme keys on the terminal.
type Loud = 'warning' | 'error'

export type Pill = {
  key: string
  hue: Hue
  icon: Icon
  label?: string
  // `fill` is the share used, 0 to 100; `mark`, how far through its window the clock is.
  meter?: { fill: number; mark?: number }
  value: string
  loud?: Loud
  // After a rule: `│ 2h 40m`.
  after?: { text: string }
  // What the pill says in words, for a reader that can't see it.
  alt: string
}

type Table = Pick<ElementTable, 'Box' | 'Text'>
type SvgTable = Extract<ElementTable, { Svg: unknown }>

// Every surface but the terminal draws Svg. (The table can't be asked: an
// element it lacks still answers `in`.)
export function pills(t: ElementTable, surface: RenderSurface, list: readonly Pill[]): RenderElement[] {
  return list.map(pill => (surface === 'terminal' ? line(t, pill) : picture(t as SvgTable, pill)))
}

// The picture

// Each hue: `mid` reads on light and dark alike; `light` and `dark` are the
// deeper and paler shades each theme gets where the surface says which it is.
const HUES: Record<Hue, { mid: string; light: string; dark: string }> = {
  sky: { mid: '#0ea5e9', light: '#0369a1', dark: '#7dd3fc' },
  pink: { mid: '#ec4899', light: '#be185d', dark: '#f9a8d4' },
  teal: { mid: '#14b8a6', light: '#0f766e', dark: '#5eead4' },
  violet: { mid: '#8b5cf6', light: '#6d28d9', dark: '#c4b5fd' },
  amber: { mid: '#f59e0b', light: '#a16207', dark: '#fcd34d' },
}

// Sizes in CSS pixels. Text is monospace, so its width follows its length.
const HEIGHT = 22
const FONT = 11
const CHAR = 6.6
const ICON = 12
const METER = 24
const BASELINE = 15

function picture({ Box, Svg }: SvgTable, pill: Pill) {
  const { source, width } = drawPill(pill)

  return (
    <Box key={pill.key} flexShrink={0}>
      <Svg source={source} alt={pill.alt} width={width} height={HEIGHT} />
    </Box>
  )
}

// The pill as SVG markup, and its width.
function drawPill(pill: Pill): { source: string; width: number } {
  const parts: string[] = []
  let x = 6
  parts.push(icon(pill.icon, x, pill.meter?.fill))
  x += ICON + 3
  if (pill.label !== undefined) {
    parts.push(text(pill.label, x, 'fg'))
    x += textWidth(pill.label) + 4
  }
  if (pill.meter !== undefined) {
    parts.push(meterBar(pill.meter, x, pill.loud))
    x += METER + 4
  }
  parts.push(text(pill.value, x, `b ${pill.loud ?? 'num'}`))
  x += textWidth(pill.value)
  if (pill.after !== undefined) {
    x += 5
    parts.push(`<rect class="rule" x="${n(x)}" y="6" width="1" height="10"/>`)
    x += 6
    parts.push(text(pill.after.text, x, 'fg'))
    x += textWidth(pill.after.text)
  }
  const width = Math.ceil(x + 7)

  return {
    width,
    source:
      `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${HEIGHT}" viewBox="0 0 ${width} ${HEIGHT}">` +
      `<style>${style(HUES[pill.hue])}</style>` +
      `<rect class="bg" width="${width}" height="${HEIGHT}" rx="${HEIGHT / 2}"/>${parts.join('')}</svg>`,
  }
}

function style(hue: { mid: string; light: string; dark: string }): string {
  const { mid, light, dark } = hue

  return (
    `text{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:${FONT}px}.b{font-weight:700}` +
    `.bg{fill:${mid};fill-opacity:.14}.fg,.fill{fill:${mid}}.num{fill:${mid}}` +
    `.ln{fill:none;stroke:${mid};stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}` +
    `.track{fill:${mid};fill-opacity:.28}.rule{fill:${mid};fill-opacity:.4}.mark{fill:#71717a}` +
    `.warning{fill:#d97706}.error{fill:#dc2626}` +
    `@media (prefers-color-scheme:light){.fg,.fill{fill:${light}}.ln{stroke:${light}}.num{fill:#3f3f46}` +
    `.mark{fill:#52525b}.warning{fill:#b45309}.error{fill:#b91c1c}}` +
    `@media (prefers-color-scheme:dark){.bg{fill-opacity:.2}.fg,.fill{fill:${dark}}.ln{stroke:${dark}}.num{fill:#e4e4e7}` +
    `.mark{fill:#d4d4d8}.warning{fill:#fbbf24}.error{fill:#f87171}}`
  )
}

function meterBar(meter: { fill: number; mark?: number }, x: number, loud: Loud | undefined): string {
  const lit = (clamp(meter.fill) / 100) * METER
  let bar = `<rect class="track" x="${n(x)}" y="9" width="${METER}" height="4" rx="2"/>`
  if (lit > 0) {
    bar += `<rect class="fill${loud === undefined ? '' : ` ${loud}`}" x="${n(x)}" y="9" width="${n(Math.max(lit, 2))}" height="4" rx="2"/>`
  }
  if (meter.mark !== undefined) {
    bar += `<rect class="mark" x="${n(x + (clamp(meter.mark) / 100) * METER - 0.75)}" y="6" width="1.5" height="10" rx=".75"/>`
  }

  return bar
}

const text = (value: string, x: number, className: string) =>
  `<text class="${className}" x="${n(x)}" y="${BASELINE}">${escape(value)}</text>`

const textWidth = (value: string) => value.length * CHAR

// 12 by 12 line icons. The pie fills to `fill` (the context's share used).
function icon(name: Icon, x: number, fill = 0): string {
  const shapes: Record<Icon, string> = {
    pie: `<circle class="ln" cx="6" cy="6" r="4.5"/>${pie(fill)}`,
    hourglass:
      '<path class="ln" d="M3 1.5h6M3 10.5h6M3.6 1.5C3.6 4.2 8.4 4.2 8.4 6S3.6 7.8 3.6 10.5M8.4 1.5C8.4 4.2 3.6 4.2 3.6 6S8.4 7.8 8.4 10.5"/>',
    gauge: '<path class="ln" d="M1.5 9a4.5 4.5 0 0 1 9 0M6 9l2.3-2.9"/>',
    calendar: '<rect class="ln" x="1.5" y="2.5" width="9" height="8" rx="1.5"/><path class="ln" d="M1.5 5.2h9M4 1.3v2.4M8 1.3v2.4"/>',
    coin:
      '<circle class="ln" cx="6" cy="6" r="4.8"/><path class="ln" d="M7.6 4.5c-.3-.5-.9-.8-1.6-.8-.9 0-1.6.5-1.6 1.1 0 .7.7.9 1.6 1.1.9.2 1.7.5 1.7 1.2s-.8 1.2-1.7 1.2c-.7 0-1.4-.3-1.7-.9M6 2.6v6.8"/>',
  }

  return `<g transform="translate(${n(x)} 5)">${shapes[name]}</g>`
}

function pie(fill: number): string {
  const share = clamp(fill) / 100
  if (share <= 0) return ''
  if (share >= 0.995) return '<circle class="fill" cx="6" cy="6" r="2.8"/>'
  const angle = share * 2 * Math.PI
  const x = 6 + 2.8 * Math.sin(angle)
  const y = 6 - 2.8 * Math.cos(angle)

  return `<path class="fill" d="M6 6V3.2A2.8 2.8 0 ${share > 0.5 ? 1 : 0} 1 ${n(x)} ${n(y)}z"/>`
}

const clamp = (percent: number) => Math.max(0, Math.min(100, percent))
const n = (value: number) => String(Math.round(value * 10) / 10)
const escape = (value: string) => value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

// The line, for a surface without Svg

const GLYPHS: Record<Icon, string> = {
  pie: '◔',
  hourglass: '⧗',
  gauge: '◷',
  calendar: '▦',
  coin: '',
}

const CELLS = 6

function line({ Box, Text }: Table, pill: Pill) {
  const color = HUES[pill.hue].mid
  const head = [GLYPHS[pill.icon], pill.label ?? ''].filter(part => part !== '').join(' ')
  // A Text takes text and Text children alone, so the parts are listed, not toggled.
  const parts = [
    ...(head === '' ? [] : [<Text color={color}>{`${head} `}</Text>]),
    ...(pill.meter === undefined ? [] : cells(Text, pill.meter, pill.loud ?? color)),
    <Text bold {...(pill.loud === undefined ? {} : { color: pill.loud })}>
      {pill.value}
    </Text>,
    ...(pill.after === undefined ? [] : [<Text dimColor>{` │ ${pill.after.text}`}</Text>]),
  ]

  return (
    <Box key={pill.key} flexShrink={0}>
      <Text>{parts}</Text>
    </Box>
  )
}

// The meter in cells: lit in the pill's color, the clock's mark where it is.
function cells(Text: Table['Text'], meter: { fill: number; mark?: number }, color: string) {
  const lit = Math.round((clamp(meter.fill) / 100) * CELLS)
  const mark = meter.mark === undefined ? -1 : Math.min(CELLS - 1, Math.floor((clamp(meter.mark) / 100) * CELLS))

  return [
    ...Array.from({ length: CELLS }, (_, at) =>
      at === mark ? <Text dimColor>┃</Text> : at < lit ? <Text color={color}>━</Text> : <Text dimColor>─</Text>,
    ),
    <Text> </Text>,
  ]
}

