// The context window as the last response left it, or, until the live window
// has a response (a fresh session, or one just compacted), as the engine
// estimates it.
export type Reading = { tokens: number; window: number; percent: number; isEstimate?: boolean }

// One rate-limit window: `five_hour` (session), `seven_day` (week), ...
export type Limit = { kind: string; percent: number; resetsAt?: number }

declare module 'claude-code' {
  interface PluginState {
    'context-meter': {
      context: Reading | null
      // This session's own limits, which decide the cache's lifetime; null before its first reply.
      limits: Limit[] | null
      // The account's limits as the band shows them: the newest reading of any session here.
      accountLimits: Limit[]
      // When `accountLimits` was read off a reply; null before any.
      accountLimitsAt: number | null
      // What the session has cost, in US dollars; null where the host keeps no ledger.
      cost: number | null
      isHidden: boolean
      isCompacting: boolean
      // When the last main-thread request started: the prompt cache's timer counts from it.
      lastRequestAt: number | null
    }
  }
}
